import{_ as d,o as a,c as e,a1 as r}from"./chunks/framework.DdbKPUhY.js";const u=JSON.parse('{"title":"UVHTTP 版本发布策略","description":"","frontmatter":{},"headers":[],"relativePath":"release-strategy.md","filePath":"release-strategy.md"}'),i={name:"release-strategy.md"};function l(o,t,n,h,s,c){return a(),e("div",null,[...t[0]||(t[0]=[r('<h1 id="uvhttp-版本发布策略" tabindex="-1">UVHTTP 版本发布策略 <a class="header-anchor" href="#uvhttp-版本发布策略" aria-label="Permalink to &quot;UVHTTP 版本发布策略&quot;">​</a></h1><h2 id="每周节奏" tabindex="-1">每周节奏 <a class="header-anchor" href="#每周节奏" aria-label="Permalink to &quot;每周节奏&quot;">​</a></h2><p>每周 5 个工作日 = 1 个版本。</p><table tabindex="0"><thead><tr><th>天</th><th>Sprint</th><th>活动</th><th>工作量</th></tr></thead><tbody><tr><td>周一</td><td>Sprint 1</td><td>开发</td><td>6-7h AI 开发</td></tr><tr><td>周二</td><td>Sprint 2</td><td>开发</td><td>6-7h AI 开发</td></tr><tr><td>周三</td><td>Sprint 3</td><td>开发</td><td>6-7h AI 开发</td></tr><tr><td>周四</td><td>Sprint 4</td><td>开发</td><td>6-7h AI 开发</td></tr><tr><td>周五</td><td>Sprint 5</td><td>测试 + 发布</td><td>全面验证 + 打 tag + 部署</td></tr></tbody></table><p>Sprint 1-4 纯开发，Sprint 5 只做测试和发布，不引入新代码。</p><h2 id="版本号规则" tabindex="-1">版本号规则 <a class="header-anchor" href="#版本号规则" aria-label="Permalink to &quot;版本号规则&quot;">​</a></h2><p>遵循 SemVer 2.0: <code>MAJOR.MINOR.PATCH</code></p><table tabindex="0"><thead><tr><th>版本类型</th><th>触发条件</th><th>每周示例</th></tr></thead><tbody><tr><td><strong>补丁 (PATCH)</strong></td><td>测试、文档、bug 修复</td><td>2.5.0 → 2.5.1</td></tr><tr><td><strong>次要 (MINOR)</strong></td><td>新功能（向后兼容）</td><td>2.5.0 → 2.6.0</td></tr><tr><td><strong>主要 (MAJOR)</strong></td><td>不兼容 API 变更</td><td>2.5.0 → 3.0.0</td></tr></tbody></table><p>每周五根据 Sprint 1-4 的内容决定版本号类型。</p><h2 id="发布流程" tabindex="-1">发布流程 <a class="header-anchor" href="#发布流程" aria-label="Permalink to &quot;发布流程&quot;">​</a></h2><h3 id="周五-sprint-5" tabindex="-1">周五 (Sprint 5) <a class="header-anchor" href="#周五-sprint-5" aria-label="Permalink to &quot;周五 (Sprint 5)&quot;">​</a></h3><ol><li><p><strong>全面测试</strong></p><ul><li><code>make -f GNUmakefile test</code> (Debug 91/91)</li><li><code>make -f GNUmakefile verify-memory-safety</code> (ASan + UBSan)</li><li><code>cd docs &amp;&amp; npm run docs:build</code></li></ul></li><li><p><strong>版本发布</strong></p><ul><li>更新 <code>VERSION</code> 文件</li><li>更新 <code>docs/guide/CHANGELOG.md</code></li><li>创建 Git tag: <code>git tag v2.x.y</code></li><li>推送 tag: <code>git push origin v2.x.y</code></li></ul></li><li><p><strong>部署</strong></p><ul><li>Push 到 main 触发 CI 自动部署</li><li>确认网站更新</li></ul></li></ol><h2 id="发布检查清单" tabindex="-1">发布检查清单 <a class="header-anchor" href="#发布检查清单" aria-label="Permalink to &quot;发布检查清单&quot;">​</a></h2><ul><li>[ ] 所有测试通过 (91/91)</li><li>[ ] ASan 零发现</li><li>[ ] UBSan 零发现</li><li>[ ] 文档构建通过</li><li>[ ] CHANGELOG 已更新</li><li>[ ] VERSION 已更新</li><li>[ ] Git tag 已创建并推送</li><li>[ ] 网站已部署</li></ul><h2 id="版本历史" tabindex="-1">版本历史 <a class="header-anchor" href="#版本历史" aria-label="Permalink to &quot;版本历史&quot;">​</a></h2><table tabindex="0"><thead><tr><th>版本</th><th>日期</th><th>Sprint</th><th>主要内容</th></tr></thead><tbody><tr><td>v2.5.1</td><td>2026-07-25</td><td>Sprint 3</td><td>测试覆盖提升 + 规格完善</td></tr><tr><td>...</td><td>...</td><td>...</td><td>...</td></tr></tbody></table>',16)])])}const b=d(i,[["render",l]]);export{u as __pageData,b as default};
